"""The legacy lesson must remain available when the final custom-domain HTTPS endpoint fails."""
from pathlib import Path
import importlib.util,json,subprocess
R=Path(__file__).resolve().parents[1]
spec=importlib.util.spec_from_file_location('redirect_old_site',R/'scripts/redirect_old_site.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
script=m.SCRIPT.split('>',1)[1].rsplit('</script>',1)[0]
runner=r'''const vm=require('node:vm');let raw='';process.stdin.on('data',x=>raw+=x);process.stdin.on('end',async()=>{const script=JSON.parse(raw);async function run(path,ok,fail){let requests=[],moves=[];const c={location:{hostname:'englishmath75.github.io',pathname:path,search:'?lesson=10',hash:'#main',replace:x=>moves.push(x)},AbortSignal:{timeout:()=>({})},fetch:(u,opts)=>{requests.push([u,opts.method]);return fail?Promise.reject(Error('TLS unavailable')):Promise.resolve({ok});}};vm.runInNewContext(script,c);await new Promise(r=>setImmediate(r));return{requests,moves};}const lesson='/pico-lab-classroom/pandas-data-lab/step-by-step.html';for(const [ok,fail] of [[false,false],[true,true]]){const r=await run(lesson,ok,fail);if(r.moves.length)throw Error('unavailable target redirected');}const good=await run(lesson,true,false);if(good.requests[0][0]!=='https://sw.englishmath.kr/step-by-step.html'||good.requests[0][1]!=='HEAD'||good.moves[0]!=='https://sw.englishmath.kr/step-by-step.html?lesson=10#main')throw Error('wrong lesson target/state');const pico=await run('/pico-lab-classroom/',true,false);if(pico.moves[0]!=='https://sw.englishmath.kr/pico.html?lesson=10#main')throw Error('wrong Pico target');console.log('PASS: final HTTPS endpoint, failed HTTP/TLS fallback, lesson query/hash and Pico target');});'''
subprocess.run(['node','-e',runner],input=json.dumps(script),text=True,check=True)
